// DBS iBanking Alert - Extract Amount and Date

function decodeEntities(s) {
  return s
    .replace(/&amp;/gi, '&')
    .replace(/&nbsp;/gi, ' ')
    .replace(/&lt;/gi, '<')
    .replace(/&gt;/gi, '>')
    .replace(/&quot;/gi, '"');
}

function stripHtml(s) {
  return decodeEntities(
    s
      .replace(/<br\s*\/?>/gi, '\n')
      .replace(/<\/(?:p|div|tr)>/gi, '\n')
      .replace(/<\/td>/gi, ' ')
      .replace(/<[^>]+>/g, '')
  ).replace(/[ \t]{2,}/g, ' ').trim();
}

const results = [];

for (const item of $input.all()) {
  const subject = item.json.subject || '';
  const plain   = item.json.text    || item.json.snippet || '';
  const html    = item.json.html    || '';

  const body    = plain.trim() ? decodeEntities(plain) : stripHtml(html);
  const content = subject + '\n' + body;

  const emailYear = item.json.date
    ? new Date(item.json.date).getFullYear()
    : new Date().getFullYear();

  // ── Amount ──────────────────────────────────────────────────────────────
  let amount = null;
  const amtPatterns = [
    /(?:SGD|S\$)\s*([\d,]+\.\d{2})/i,
    /(?:SGD|S\$)\s*([\d,]+)/i,
    /amount[:\s]+(?:SGD\s*)?([\d,]+\.?\d*)/i,
    /of\s+(?:SGD|S\$)\s*([\d,]+\.?\d*)/i,
    /(?:debit|credit)(?:ed)?[^\d]{0,20}([\d,]+\.\d{2})/i,
  ];
  for (const re of amtPatterns) {
    const m = content.match(re);
    if (m) { amount = parseFloat(m[1].replace(/,/g, '')); break; }
  }

  // ── Date ────────────────────────────────────────────────────────────────
  let txnDate = null;
  const datePatterns = [
    /(\d{1,2}\s+(?:Jan|Feb|Mar|Apr|May|Jun|Jul|Aug|Sep|Oct|Nov|Dec)[a-z]*\.?\s+\d{4})/i,
    /Date\s*[&]?\s*Time\s*:\s*(\d{1,2}\s+(?:Jan|Feb|Mar|Apr|May|Jun|Jul|Aug|Sep|Oct|Nov|Dec)[a-z]*\.?)(?:\s+\d{1,2}:\d{2})?/i,
    /Date\s*:\s*(\d{1,2}\s+(?:Jan|Feb|Mar|Apr|May|Jun|Jul|Aug|Sep|Oct|Nov|Dec)[a-z]*\.?)(?:\s+\d{4})?/i,
    /dated?\s+(\d{1,2}\s+(?:Jan|Feb|Mar|Apr|May|Jun|Jul|Aug|Sep|Oct|Nov|Dec)[a-z]*\.?)(?:\s+\d{4})?/i,
    /(\d{2}[\/-]\d{2}[\/-]\d{4})/,
    /(\d{4}-\d{2}-\d{2})/,
  ];
  for (const re of datePatterns) {
    const m = content.match(re);
    if (m) {
      let d = m[1].trim();
      if (!/\d{4}/.test(d)) d = d + ' ' + emailYear;
      txnDate = d;
      break;
    }
  }

  results.push({
    json: {
      emailId:      item.json.id,
      subject,
      from:         item.json.from,
      emailDate:    item.json.date,
      amount,
      currency:     'SGD',
      txnDate,
      extractionOk: !!(amount && txnDate),
      _debug: {
        amountFound: amount  !== null,
        dateFound:   txnDate !== null,
        bodyPreview: body.substring(0, 600)
      }
    }
  });
}

return results;
